namespace sv_91ee4ef64356406fad2210ac1baf4060.Client.Models;

public sealed record StatusUpdate(DateTime Timestamp, string Status, string Location);

public sealed record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTime? EstimatedDelivery,
    IReadOnlyList<StatusUpdate> Updates);

using sv_91ee4ef64356406fad2210ac1baf4060.Client.Models;

namespace sv_91ee4ef64356406fad2210ac1baf4060.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct = default);
}

using sv_91ee4ef64356406fad2210ac1baf4060.Client.Models;

namespace sv_91ee4ef64356406fad2210ac1baf4060.Client.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new ShipmentDetails(
            TrackingNumber: "PKG-001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTime(2026, 7, 5),
            Updates: new List<StatusUpdate>
            {
                new(new DateTime(2026, 6, 28, 9, 0, 0), "Picked Up", "New York, NY"),
                new(new DateTime(2026, 6, 29, 14, 30, 0), "Departed Facility", "New York, NY"),
                new(new DateTime(2026, 6, 30, 8, 15, 0), "Arrived at Hub", "Chicago, IL"),
            }),

        ["PKG-002"] = new ShipmentDetails(
            TrackingNumber: "PKG-002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTime(2026, 6, 30),
            Updates: new List<StatusUpdate>
            {
                new(new DateTime(2026, 6, 25, 10, 0, 0), "Picked Up", "Seattle, WA"),
                new(new DateTime(2026, 6, 26, 16, 0, 0), "In Transit", "Portland, OR"),
                new(new DateTime(2026, 6, 28, 11, 45, 0), "Out for Delivery", "San Francisco, CA"),
                new(new DateTime(2026, 6, 28, 15, 20, 0), "Delivered", "San Francisco, CA"),
            }),

        ["PKG-003"] = new ShipmentDetails(
            TrackingNumber: "PKG-003",
            Status: "Processing",
            Location: "Dallas, TX",
            EstimatedDelivery: new DateTime(2026, 7, 8),
            Updates: new List<StatusUpdate>
            {
                new(new DateTime(2026, 6, 30, 17, 0, 0), "Label Created", "Dallas, TX"),
            }),
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct = default)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

